INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("イベントでは、特別なストーリーをお楽しみいただけます。\n閲覧可能なストーリーを読むと、次のお話が解放されていきますよ。\nストーリーの閲覧によって達成されるミッションもあるのだとか。", 1, 1, 1, 1011);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("イベントクエストやボスバトルに挑戦してみましょう。ボスバトルは\n特定のイベントストーリーを閲覧するか、イベントクエスト・ボス画面で\n「解放する」を選択すると挑戦可能になりますよ。", 1, 2, 2, 1021);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("報酬交換では「イベント報酬券」と様々なアイテムを交換できます。\n目玉となるリセット対象報酬を引くことで、より多くのアイテムが\n獲得できる次のラインナップへと進めるそうです。", 1, 4, 4, 1041);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("ボスバトルには３種の難易度がございます。\n各難易度ごとにボスの強さやバトルの特徴が異なりますので、\n準備をしっかりして、気を引き締めて挑みましょう。", 1, 5, 5, 1051);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("イベントでは、特別なストーリーをお楽しみいただけます。\n閲覧可能なストーリーを読むと、次のお話が解放されていきますよ。", 2, 1, 1, 2011);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("イベントクエストやボスバトルに挑戦してみましょう。ボスバトルは\n特定のイベントストーリーを閲覧するか、イベントクエスト・ボス画面で\n「解放する」を選択すると挑戦可能になりますよ。", 2, 2, 2, 2021);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("報酬交換では「イベント報酬券」と様々なアイテムを交換できます。\n目玉となるリセット対象報酬を引くことで、より多くのアイテムが\n獲得できる次のラインナップへと進めるそうです。", 2, 4, 4, 2041);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("ボスバトルには２種の難易度がございます。\n各難易度ごとにボスの強さやバトルの特徴が異なりますので、\n準備をしっかりして、気を引き締めて挑みましょう。", 2, 5, 5, 2051);
